//! CPython-exact helpers for the Rust port (docs/rust-port-guide.md).
//!
//! Every function here must give bit-identical results (or byte-identical strings) to CPython 3.14,
//! checked against fixtures generated by `scripts/port/pycompat_fixtures.py`
//! (`cargo test` in this crate reads `runs/_port/fixtures/pycompat.jsonl`).

pub mod fmt;
pub mod json;
pub mod math;
pub mod random;
pub mod statistics;

pub use fmt::{fixed, pyfloat, pyround, pyround_int, signed};
pub use math::{comb, fsum};
pub use random::Random;
